[ApiController]
[Route("api/auth")]
public class AuthController : ControllerBase
{
    private readonly DemoUsersOptions _options;
    private readonly SessionStore _sessions;

    public AuthController(IOptions<DemoUsersOptions> options, SessionStore sessions)
    {
        _options = options.Value;
        _sessions = sessions;
    }

    public record LoginRequest(string Username, string Password);
    public record LoginResponse(string Token, string Username, string Role);

    [HttpPost("login")]
    public ActionResult<LoginResponse> Login([FromBody] LoginRequest request)
    {
        var user = _options.Users.FirstOrDefault(u =>
            u.Username == request.Username && u.Password == request.Password);

        if (user is null)
        {
            return Unauthorized(new { error = "Invalid username or password." });
        }

        var token = _sessions.Create(new UserSession(user.Username, user.Role));
        return Ok(new LoginResponse(token, user.Username, user.Role));
    }

    [HttpPost("logout")]
    public IActionResult Logout()
    {
        var header = Request.Headers.Authorization.ToString();
        if (header.StartsWith("Bearer "))
        {
            _sessions.Remove(header["Bearer ".Length..]);
        }

        return NoContent();
    }
}
namespace InvoiceApp.Api.Auth;

/// <summary>Requires a valid bearer [REDACTED] on every /api call except sign-in.</summary>
public class SessionAuthMiddleware
{
    private const string BearerPrefix = "Bearer ";
    private readonly RequestDelegate _next;
    private readonly SessionStore _sessions;

    public SessionAuthMiddleware(RequestDelegate next, SessionStore sessions)
    {
        _next = next;
        _sessions = sessions;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var path = context.Request.Path;
        var needsSession = path.StartsWithSegments("/api") && !path.StartsWithSegments("/api/auth/login");

        if (needsSession)
        {
            var header = context.Request.Headers.Authorization.ToString();
            var token = header.StartsWith(BearerPrefix) ? header[BearerPrefix.Length..] : null;
            var session = _sessions.Get(token);

            if (session is null)
            {
                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                await context.Response.WriteAsJsonAsync(new { error = "A valid signed-in session is required." });
                return;
            }

            context.Items[HttpContextExtensions.SessionKey] = session;
        }

        await _next(context);
    }
}

public static class HttpContextExtensions
{
    public const string SessionKey = "session";

    public static UserSession GetSession(this HttpContext context) =>
        (UserSession)context.Items[SessionKey]!;
}
