    23	    // handles arbitrary JSON exponents without overflowing during validation.
    24	    private static (string Coefficient, BigInteger Exponent) Normalize(string number)
    25	    {
    26	        var exponentPosition = number.IndexOfAny(new[] { 'e', 'E' });
    27	        var exponent = exponentPosition < 0 ? BigInteger.Zero : BigInteger.Parse(number[(exponentPosition + 1)..], CultureInfo.InvariantCulture);
    28	        var significand = exponentPosition < 0 ? number : number[..exponentPosition];
    29	        var point = significand.IndexOf('.');
    30	        if (point >= 0) { exponent -= significand.Length - point - 1; significand = significand.Remove(point, 1); }
    31	        var negative = significand.StartsWith('-');
    32	        var digits = significand.TrimStart('-').TrimStart('0');
    33	        if (digits.Length == 0) return ("0", BigInteger.Zero);
    34	        var trimmed = digits.TrimEnd('0');
    35	        exponent += digits.Length - trimmed.Length;
    36	        return ((negative ? "-" : "") + trimmed, exponent);
    37	    }
